-- Darts Trainer: gemeinsame Cricket-Datenbank
create table if not exists public.cricket_games (
  id text primary key,
  started_at timestamptz not null,
  finished_at timestamptz not null,
  rounds integer not null check (rounds > 0),
  winner_name text not null,
  players jsonb not null,
  created_at timestamptz not null default now()
);

create index if not exists cricket_games_finished_at_idx
  on public.cricket_games (finished_at desc);

alter table public.cricket_games enable row level security;

drop policy if exists "cricket_games_public_read" on public.cricket_games;
create policy "cricket_games_public_read"
on public.cricket_games for select
to anon, authenticated
using (true);

drop policy if exists "cricket_games_public_insert" on public.cricket_games;
create policy "cricket_games_public_insert"
on public.cricket_games for insert
to anon, authenticated
with check (
  jsonb_typeof(players) = 'array'
  and jsonb_array_length(players) between 2 and 20
);

insert into public.cricket_games
(id, started_at, finished_at, rounds, winner_name, players)
